/* ── remember：板子记住孩子说过的事（决赛加） ────────────────────
 *
 * 工具表里多一条 remember。孩子在聊天里说到关于自己的事 —— 最喜欢什么、
 * 养了什么宠物、生日、怕什么、在期待什么 —— 模型调一次这个工具，
 * 那句话就存下来了；kid_buddy 每轮把最近几条注入提示词，下次提起时它接得上。
 *
 * **为什么由模型决定记什么**：写死在应用里的关键词表只能覆盖提前想到的说法，
 * 而「哪句值得记」本来就是语义判断。这也和这个作品一贯的做法一致 ——
 * 判断在模型、执行在板子。
 *
 * 存储就是一个纯文本文件，一行一条，FIFO 封顶。kid_buddy 那边读它。
 * 实现放在这里而不是新开一个文件，是为了不动 CMakeLists 的源文件列表。
 */

#define KID_FACTS_PATH   AGENT_DATA_DIR "/kid_buddy_facts.txt"
#define KID_FACTS_MAX    32     /* 存放上限，超了丢最旧的 */
#define KID_FACTS_LINE   96     /* 单条上限（字节） */

static int kid_facts_read(char (*lines)[KID_FACTS_LINE], int max)
{
    FILE *f = fopen(KID_FACTS_PATH, "r");
    int   n = 0;

    if (f == NULL) {
        return 0;
    }

    while (n < max && fgets(lines[n], KID_FACTS_LINE, f) != NULL) {
        size_t l = strlen(lines[n]);

        while (l > 0 && (lines[n][l - 1] == '\n' || lines[n][l - 1] == '\r')) {
            lines[n][--l] = '\0';
        }

        if (l > 0) {
            n++;
        }
    }

    fclose(f);
    return n;
}

static int kid_facts_write(char (*lines)[KID_FACTS_LINE], int n)
{
    FILE *f = fopen(KID_FACTS_PATH, "w");
    int   i;

    if (f == NULL) {
        return ERROR;
    }

    for (i = 0; i < n; i++) {
        fprintf(f, "%s\n", lines[i]);
    }

    fclose(f);
    return OK;
}

int tool_remember_execute(const char *input_json, char *output,
                          size_t output_size)
{
    /* 只跑在 Agent 主循环这一个线程上，静态缓冲是安全的 ——
     * 换来的是不用在栈上放 3KB。 */
    static char s_lines[KID_FACTS_MAX][KID_FACTS_LINE];

    cJSON      *root;
    const char *fact;
    char        clean[KID_FACTS_LINE];
    size_t      n = 0;
    size_t      i;
    int         count;

    root = cJSON_Parse(input_json);

    if (root == NULL) {
        snprintf(output, output_size, "{\"error\":\"bad json\"}");
        return ERROR;
    }

    fact = cJSON_GetStringValue(cJSON_GetObjectItem(root, "fact"));
    cJSON_Delete(root);

    if (fact == NULL || fact[0] == '\0') {
        snprintf(output, output_size, "{\"error\":\"fact is empty\"}");
        return ERROR;
    }

    /* 一条事实必须压成一行：换行会把文件格式撑破 */
    for (i = 0; fact[i] != '\0' && n < KID_FACTS_LINE - 1; i++) {
        char c = fact[i];
        clean[n++] = (c == '\n' || c == '\r' || c == '\t') ? ' ' : c;
    }

    while (n > 0 && clean[n - 1] == ' ') {
        n--;
    }

    clean[n] = '\0';

    if (n == 0) {
        snprintf(output, output_size, "{\"error\":\"fact is empty\"}");
        return ERROR;
    }

    count = kid_facts_read(s_lines, KID_FACTS_MAX);

    /* 记过同一条就不重复 */
    for (i = 0; i < (size_t)count; i++) {
        if (strcmp(s_lines[i], clean) == 0) {
            snprintf(output, output_size,
                     "{\"ok\":true,\"note\":\"already known\",\"total\":%d}",
                     count);
            return OK;
        }
    }

    /* 满了丢最旧的一条 */
    if (count >= KID_FACTS_MAX) {
        memmove(s_lines[0], s_lines[1],
                (size_t)(KID_FACTS_MAX - 1) * KID_FACTS_LINE);
        count = KID_FACTS_MAX - 1;
    }

    strncpy(s_lines[count], clean, KID_FACTS_LINE - 1);
    s_lines[count][KID_FACTS_LINE - 1] = '\0';
    count++;

    if (kid_facts_write(s_lines, count) != OK) {
        snprintf(output, output_size, "{\"error\":\"write failed\"}");
        return ERROR;
    }

