/* 安全追加：**绝不能写 off += snprintf(buf+off, size-off, ...)** ——
 * snprintf 返回的是「本来想写多少」，一旦超了 size-off 就会下溢成巨大的
 * size_t，下一次写就变成无边界写。（这个坑在技能文件那条路径上踩过。） */
static void facts_append(char *buf, size_t cap, size_t *off, const char *text)
{
    size_t n = strlen(text);

    if (*off >= cap - 1 || n == 0)
      {
        return;
      }

    if (n > cap - 1 - *off)
      {
        n = cap - 1 - *off;
      }

    memcpy(buf + *off, text, n);
    *off += n;
    buf[*off] = '\0';
}

