            n++;
        }
    }

    fclose(f);
    return n;
}

static int kid_lines_write(const char *path, char (*lines)[KID_LINE], int n)
{
    FILE *f = fopen(path, "w");
    int   i;

    if (f == NULL) {
        return ERROR;
    }

    for (i = 0; i < n; i++) {
        fprintf(f, "%s\n", lines[i]);
    }

    fclose(f);
    return OK;
