/* ── 星芽岛的世界状态（v2.85） ──────────────────────────────────────
 *
 * remember_world 每次写一行，文件本身就是从旧到新的顺序，最多 WORLD_MAX
 * 行。这里不做缓存：每轮故事都要用最新的状态，而且文件只有两三 KB，
 * littlefs 读一遍是微秒级 —— 省这点开销不值得冒“刚记的事这轮看不到”的险。
 */
static char g_world[WORLD_MAX][WORLD_LINE];
static int  g_world_count = 0;

static void world_reload(void)
{
    FILE *f;
    char  line[WORLD_LINE];
    int   n = 0;

    g_world_count = 0;

    f = fopen(WORLD_PATH, "r");

    if (f == NULL)
      {
        return;
      }

    while (n < WORLD_MAX && fgets(line, sizeof(line), f) != NULL)
      {
        size_t l = strlen(line);

        while (l > 0 && (line[l - 1] == '\n' || line[l - 1] == '\r'))
          {
            line[--l] = '\0';
          }

        if (l == 0)
          {
            continue;
          }

        strncpy(g_world[n], line, WORLD_LINE - 1);
        g_world[n][WORLD_LINE - 1] = '\0';
        n++;
      }

    fclose(f);
    g_world_count = n;
}

/* 把世界状态拼成一段提示。不是故事模式、或者还没有任何记录，就返回空串。 */
static void world_build_block(char *buf, size_t cap)
{
    size_t off = 0;

    buf[0] = '\0';

    if (!g_story_mode)
      {
        return;
      }

    world_reload();

    if (g_world_count <= 0)
      {
        return;
      }

    facts_append(buf, cap, &off,
                 "\n[世界状态：星芽岛]\n"
                 "下面这些事已经发生过，是既定事实。不要重新打开同一个宝箱、"
                 "不要把已经拿走的东西放回去，也不要当作没发生；"
                 "孩子提起时，按这里说的接下去。\n");

    for (int i = 0; i < g_world_count; i++)
      {
        facts_append(buf, cap, &off, "- ");
        facts_append(buf, cap, &off, g_world[i]);
        facts_append(buf, cap, &off, "\n");
      }
}

