/* 摸头：读一次接近传感器。
 *
 * 跑在 LVGL 线程上（poll_timer_cb 是 lv_timer 回调），所以必须用
 * O_NONBLOCK —— 这个驱动是 fetch 型的，阻塞读会一直等到下一帧数据，
 * 把整个界面卡住。
 *
 * 只在「远 -> 近」这个边沿触发一次。手一直放在那里不会每 3 秒抬一次头；
 * 拿走再凑过来才会再触发。第一帧只用来初始化状态，避免开机时手正好
 * 在传感器前面就莫名其妙抬一次头。 */
static void prox_poll(int64_t now)
{
    struct sensor_prox p;
    ssize_t n;

    if (g_prox_fd < 0)
      {
        if (now < g_prox_next_open_ms)
          {
            return;
          }

        g_prox_fd = open(PROX_DEV_PATH, O_RDONLY | O_NONBLOCK);
        if (g_prox_fd < 0)
          {
            g_prox_next_open_ms = now + PROX_OPEN_RETRY_MS;
            return;
          }

        syslog(LOG_INFO, "[kid_buddy] 接近传感器已打开：%s\n",
               PROX_DEV_PATH);
      }

    n = read(g_prox_fd, &p, sizeof(p));
    if (n != (ssize_t)sizeof(p))
      {
        /* EAGAIN：这一拍还没有新样本，下一拍再看。 */
        return;
      }

    if (!g_prox_have_sample)
      {
        g_prox_have_sample = 1;
        g_prox_near = (p.proximity <= PROX_ENTER);
        return;
      }

    if (!g_prox_near && p.proximity <= PROX_ENTER)
      {
        g_prox_near = 1;
        g_face_peek_until = now + FACE_PEEK_HOLD_MS;
      }
    else if (g_prox_near && p.proximity >= PROX_EXIT)
      {
        g_prox_near = 0;
      }
}

