/* ── 星芽岛的世界状态（v2.85） ──────────────────────────────────────
 *
 * remember_world 每次写一行，文件本身就是从旧到新的顺序，最多 WORLD_MAX
 * 行。这里不做缓存：每轮故事都要用最新的状态，而且文件只有两三 KB，
 * littlefs 读一遍是微秒级 —— 省这点开销不值得冒“刚记的事这轮看不到”的险。
 */
static char g_world[WORLD_MAX][WORLD_LINE];
static int  g_world_count = 0;

static void world_reload(void)
{
    FILE *f;
    char  line[WORLD_LINE];
    int   n = 0;

    g_world_count = 0;

    f = fopen(WORLD_PATH, "r");

    if (f == NULL)
      {
        return;
      }

    while (n < WORLD_MAX && fgets(line, sizeof(line), f) != NULL)
      {
        size_t l = strlen(line);

        while (l > 0 && (line[l - 1] == '\n' || line[l - 1] == '\r'))
          {
            line[--l] = '\0';
          }

        if (l == 0)
          {
            continue;
          }

        strncpy(g_world[n], line, WORLD_LINE - 1);
        g_world[n][WORLD_LINE - 1] = '\0';
        n++;
      }

    fclose(f);
    g_world_count = n;
}

